import { homepageCopy as copy } from '../i18n/homepage.ts'
import { SITE_ORIGIN, PUBLISHING_UPDATED, PUBLIC_SAMPLES, publicPaths, publishingIdentity } from './site-config.ts'
import { learningPages, learningCards } from './learning-pages.ts'
import { productQuestions } from '../report/product-questions.ts'

type Identity = ReturnType<typeof publishingIdentity>
type Page = { path: string; title: string; description: string; body: string; image?: string; noindex?: boolean; article?: boolean }
const escape = (value: string) => value.replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[c]!)
const para = (...items: string[]) => items.map(text => `<p>${escape(text)}</p>`).join('')
const section = (title: string, body: string) => `<section class="public-chapter"><h2>${escape(title)}</h2>${body}</section>`
const update = `<p class="public-updated">Updated <time datetime="${PUBLISHING_UPDATED}">19 October 2026</time> · The Fate Key</p>`
const mail = (email: string) => `mailto:${encodeURIComponent(email).replace('%40','@')}`
const key = '<svg viewBox="0 0 60 124" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="30" cy="33" r="22"/><circle cx="30" cy="33" r="16"/><path d="m30 20 3 10 10 3-10 3-3 10-3-10-10-3 10-3Z M27 55v59l3 6 3-6V55 M33 88h13v6H33 M33 104h13v6H33"/></svg>'

function cards() {
  return `<div class="public-cards">${PUBLIC_SAMPLES.map(item => `<article><a href="/samples/${item.slug}/"><img src="/images/reports/${'imageKind' in item ? item.imageKind : item.kind}-v1-640.webp" alt="" width="640" height="427" loading="lazy"/><div><h2>${escape(item.title)}</h2><p>${escape(item.description)}</p><span>Read the complete fictional sample →</span></div></a></article>`).join('')}</div>`
}

function home() {
  return `<section class="public-home-intro"><p class="public-eyebrow">Ancient wisdom. Modern insight.</p><h1>Your Story Holds the Key to a Brighter Tomorrow.</h1>${para('Explore personality, relationships, work and everyday choices through a traditional Korean birth-chart reading, explained in everyday English.','Your free snapshot and personal preview are calculated in your browser. Public sample reports show the complete question list and a fictional example answer for every question. They contain no customer data or personal chart conclusions.')}<a class="public-button" href="/samples/">Explore the sample readings →</a><p class="public-small">The interactive birth form requires JavaScript. The public sample readings and guides below can be read without it.</p></section><section><p class="public-eyebrow">Read a little first</p><h2>Choose a subject that matters to you</h2>${cards()}</section>${section('What goes into a reading',para('Saju uses the year, month, day and hour of birth as the starting point for a traditional chart. Your local clock time and birthplace help the calculator apply the relevant time zone and its historical daylight-saving rules. An unknown birth time stays unknown; hour-based interpretations are left out.','The report connects calculated symbols with personal questions and everyday reflection. Each paid report answers its listed questions and includes clear explanations, relevant timing and a premium PDF keepsake. Public previews demonstrate the layout without exposing private or complete paid answers.'))}${section('Free access and planned reports',para('Free snapshots and short previews are available to explore. Paid purchasing is not open; no payment is collected. Current report prices in USD are shown on each product card.'))}<aside class="public-notice">Traditional Saju interpretation is for personal reflection. It is not a scientific personality assessment, a promise about future events or professional medical, financial or legal advice.</aside>`
}

