function safeSampleBody(kind: string, title: string) {
  const definitions = productQuestions(kind as Parameters<typeof productQuestions>[0])
  const questions = definitions.map(question => question.title)
  // Bind each fictional answer to a stable question ID. The ID lists describe
  // the legacy sample prose's intended subjects; question order is never used
  // to select an answer at render time.
  const sampleQuestionIds: Record<string, readonly string[]> = {
    complete: ['personality','social','career','money','love','patterns','q-turning-points'],
    career: ['two-work-layers','proof-of-skill','money-commitments','working-style','feedback-and-boundaries','work-chapters','career-plan'],
    compatibility: ['two-styles','two-directions','q-conflict','q-love-language','chart-patterns','support-each-other','shared-week'],
    year: ['annual-theme','q-year-focus','annual-money','annual-work','annual-connections','annual-cycle-context','annual-plan'],
    business: ['founder-style','offer-test','team-decisions','delivery-capacity','customer-communication','business-chapters','business-plan'],
    wellbeing: ['everyday-pace','visible-elements','workload-rhythm','q-pressure','support-and-space','balance-week','q-balance-action'],
    bundle: ['collection-q1','collection-q2','collection-q3','collection-q4','collection-q5','collection-q6','collection-q7','collection-q8','collection-q9','collection-q10'],
  }
  const legacyAnswers = SAMPLE_ANSWERS[kind]
  const ids = sampleQuestionIds[kind]
  if (!legacyAnswers || !ids || legacyAnswers.length !== ids.length) throw new Error('Sample answer mapping must match the approved question IDs for ' + kind)
  const answersById = Object.fromEntries(ids.map((id, index) => [id, legacyAnswers[index]]))
  if (kind === 'bundle') Object.assign(answersById, {
    'collection-q1': 'In this fictional example, three themes stand out: thoughtful observation, steady skill-building and a need for clear, dependable relationships. They are separate parts of Avery’s story, not predictions.',
    'collection-q2': 'Avery’s clearest fictional opportunity is to turn careful observation into a practical skill others can use. A real reading would connect this to the buyer’s verified chart and circumstances.',
    'collection-q3': 'The main challenge in this example is delaying action while trying to make every detail certain. That can reduce stress in the short term but also postpone useful choices.',
    'collection-q4': 'Avery’s careful nature supports reliable work and considered spending, while close relationships work best with clear, honest communication. These areas connect through a shared preference for trust and consistency.',
    'collection-q5': 'Avery repeatedly takes responsibility early, then reviews the details again before asking what is truly needed. This is a behavioural loop, separate from the challenge of delaying a decision.',
    'collection-q6': 'This fictional sample cannot identify important years because it has no verified chart timing calculation. A personal report should name years only when its calculation supports them.',
    'collection-q7': 'For the three years following a purchase, this fictional example cannot rank specific years without verified timing calculations. It should not invent dates or imply a forecast.',
    'collection-q8': 'A strength Avery may overlook is noticing small practical problems before they grow. In this example, that attention can help a team improve a process.',
    'collection-q9': 'Avery’s fictional life feels more fulfilling when work has a clear purpose, money choices feel manageable and close relationships allow honest, dependable support.',
    'collection-q10': 'Avery’s personal closing insight is to trust careful observation, then let a clear next step be enough. The example leaves room for the person’s own choices and experience.',
  })
  if (definitions.some(question => !answersById[question.id])) throw new Error('Missing fictional answer for a question ID in ' + kind)
  const items = questions.map(question => '<li>' + escape(question) + '</li>').join('')
  const samplePages = definitions.map(question =>
    '<section class="public-chapter public-sample-answer" data-question-id="' + escape(question.id) + '"><p class="public-eyebrow">QUESTION ' + String(question.order).padStart(2, '0') + ' · FICTIONAL EXAMPLE</p><h2>' + escape(question.title) + '</h2><p><strong>Example answer:</strong> ' + escape(answersById[question.id]) + '</p><aside class="public-sample-note"><strong>What a personal report adds</strong><p>It uses the buyer’s own verified birth chart to explain whether this theme applies, what supports the interpretation and any relevant timing. This sample contains no customer data or personal chart result.</p></aside></section>'
  ).join('')
  return '<article class="public-reading public-preview-only public-sample-report">' +
    '<header class="public-sample-cover"><div class="public-cover-copy"><p class="public-eyebrow">THE FATE KEY · COMPLETE FICTIONAL SAMPLE</p><h2>' + escape(title) + '</h2><p>A full example of the report’s question-by-question structure and writing style.</p><p class="public-small">Fictional reader: Avery · No customer birth details or personal chart calculations are used.</p><p class="public-eyebrow">SAMPLE ONLY · NOT A PERSONAL READING</p></div><svg class="public-cover-art" viewBox="0 0 300 250" role="img" aria-label="Decorative golden key, crescent moon and orbit illustration"><circle cx="165" cy="125" r="87" fill="none" stroke="#d2af72" stroke-width="1" opacity=".65"/><circle cx="165" cy="125" r="67" fill="none" stroke="#d2af72" stroke-width="1" stroke-dasharray="2 7" opacity=".7"/><path d="M201 46a61 61 0 1 0 47 91 55 55 0 0 1-47-91Z" fill="#d8b778" opacity=".94"/><circle cx="68" cy="69" r="3" fill="#f0d69f"/><path d="m68 57 3 9 9 3-9 3-3 9-3-9-9-3 9-3Z" fill="#f0d69f"/><circle cx="237" cy="203" r="3" fill="#f0d69f"/><path d="M104 161a30 30 0 1 1 21 29l-17 17 10 10-9 9-10-10-12 12-10-10 29-29a30 30 0 0 1-2-28Zm30-18a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z" fill="none" stroke="#e5c47e" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg></header>' +
    '<section class="public-chapter" id="sample-contents"><h2>Inside this report</h2><p>This example follows all ' + questions.length + ' questions in the paid report. Every answer below is fictional and written only to demonstrate the format.</p><ol>' + items + '</ol></section>' +
    '<section class="public-chapter public-sample-walkthrough"><p class="public-eyebrow">COMPLETE EXAMPLE REPORT · FICTIONAL</p><h2>A question-led reading, from first answer to closing note</h2><p>These sample answers are not calculated from Saju and do not describe a real customer. A purchased report uses the buyer’s verified birth details and explains the chart themes relevant to their questions.</p></section>' +
    samplePages +
    '<section class="public-chapter public-sample-closing"><p class="public-eyebrow">CLOSING SUMMARY · FICTIONAL EXAMPLE</p><h2>A final note for Avery</h2><p>This fictional reading brings its themes together without treating them as fixed outcomes. It shows how a report can answer each question, explain a practical pattern and leave room for the reader’s own experience.</p><p><strong>In a purchased report, the closing summary connects the answers to your birth chart and the questions you asked.</strong></p></section>' +
    '<section class="public-chapter"><h2>What the complete paid report adds</h2><p>Personal answers to every question, chart-based explanations, relevant timing where supported, connected insights, and the complete premium letter-style PDF.</p><p class="public-small">This public sample is a complete illustrative structure, not a customer report or a substitute for the personalised paid reading.</p></section>' +
    '<p><a class="public-button" href="/#reports">Explore the report options →</a></p></article>'
}
function about(identity: Identity) {
  return update+para('The Fate Key is an independent digital publishing project about traditional Korean Saju and everyday reflection. We publish English explanations, short design samples and a browser-based tool for exploring birth-chart themes.','Our aim is to make an unfamiliar chart easier to read. A useful passage should explain the theme, show a situation you can recognise, offer something practical to try and make room for your experience to disagree.')+
    section('How the readings are made',para('The chart is calculated by the open-source Orrery engine. The English report is assembled from coded interpretation templates and original editorial exercises selected by calculated chart relationships. It is not a live consultation with a fortune-teller.','AI assistance has been used to draft, edit and check the English wording. The public examples are disclosed as fictional inputs. We do not present an AI check as an independent human editor’s review, professional certification or evidence that predictions are accurate.','The practical situations are examples you choose, not events inferred from a birthday. When a report asks you to record costs, workload, promises or another person’s words, those real facts provide the detail the chart cannot know.'))+
    section('What the calculations do and do not establish',para('The calculator uses local birth details, an IANA time zone and the site’s documented clock or solar-time conventions. Historical time records and boundaries can require care. Two calculators using different conventions can disagree near a boundary.','An unknown hour is excluded. Visible element counts do not diagnose chart strength, chart structure or useful elements. Annual and monthly examples use the reference points stated in the report; they are not forecasts of every day in a calendar month.','Passing software tests checks specified calculations and consistency. It does not prove that a traditional interpretation describes a person or predicts an event. The reports have not received independent scientific validation or expert certification.'))+
    section('Editorial standards',`<p><a href="/editorial-policy/">Read our writing, source and correction standards</a>.</p><ul><li>Keep the main explanation in everyday English and explain the calculated source behind a theme.</li><li>Use short public samples so readers can inspect the design and question list before making a purchase decision.</li><li>Distinguish a symbolic interpretation from facts about a person’s actual life.</li><li>Offer conditional choices, small experiments and review questions rather than guaranteed outcomes.</li><li>Do not invent customer testimonials, user counts, success rates or official endorsements.</li><li>Label decorative category artwork as illustration. The category covers were created with AI assistance; they do not depict verified clients or results.</li></ul>`)+
    section('The service today',para('The free snapshot, short personal previews, guides and public design samples are available. Paid checkout, customer accounts and payment-based report issuing are not active. Saved Details stores information in your browser; it is not an online customer account.'))+
    section('Sources and corrections',`<p>The engine is based on <a href="https://github.com/rath/orrery">Orrery</a>. <a href="https://github.com/aushopfinds-design/orrery/tree/feature/english-saju-report-20261013">Source for this site</a> is available on GitHub. Cultural symbol references are linked in the readings where they are used.</p><p>For entering birth details, understanding a report or clearing browser data, see the <a href="/reading-guide/">Reading Guide</a> and <a href="/help/">Help Centre</a>.${identity.contactEmail ? ` For a correction or question, use our <a href="/contact/">contact page</a>.` : ''}</p>`)
}

function privacy(identity: Identity) {
  return update+para('This notice describes how the current The Fate Key website handles information. The site provides browser-calculated readings and public educational examples. It does not currently operate paid checkout or customer accounts.')+
    section('Birth details and private previews',para(copy['site.privacy.calc.text'],copy['site.privacy.storage.text'],copy['site.privacy.backup.text'],'Do not enter another person’s birth information unless you are entitled to use it. On a shared device, consider whether you want to save a named profile. A downloaded backup can be read by anyone who can open that file.'))+
    section('Browser storage and cookies',para('The site uses local storage for reading preferences, the last submitted first-person form and named saved profiles. A tab’s session storage can remember the personal preview, second person and selected year. Theme and language preferences may also be stored locally. These are browser-storage features; they are not an online account or a guarantee of encrypted storage.','The Fate Key records basic visit, reading-completion, report-selection, checkout-opening and report-opening events in its own hosting logs. These events contain only the event name, report category and test or production environment. They do not include birth details, names, order identifiers, page URLs or a persistent tracking identifier. Do Not Track is respected. Counts describe activity rather than unique people or verified sales. No third-party analytics or advertising cookie script is installed. The current application does not use an advertising profile to calculate a reading. Browser settings can block or remove storage, and a free reading can still be calculated when saved storage is unavailable.'))+
    section('Connections to other services',para(copy['site.privacy.search.text'],'The browser’s request to this site and its hosting provider includes connection information such as an IP address, user agent, requested page and time of access. Vercel hosts the site. The interactive app loads fonts from Google Fonts and jsDelivr. Those services receive the connection information needed to handle their requests; their logging and retention are governed by their own practices.','A birthplace search passes the typed place name and selected country through this site’s search endpoint to Photon, using OpenStreetMap data. Birth dates, birth times and saved names are not included in those search requests. Countries and providers may process connection information outside your country.'))+
    `<ul class="public-service-links"><li><a href="https://vercel.com/legal/privacy-policy">Vercel privacy information</a></li><li><a href="https://policies.google.com/privacy">Google privacy information</a></li><li><a href="https://www.jsdelivr.com/terms/privacy-policy">jsDelivr privacy information</a></li><li><a href="https://photon.komoot.io/">Photon place search</a> · <a href="https://www.openstreetmap.org/copyright">OpenStreetMap attribution</a></li></ul>`+
    section('Advertising and your choices',para('As of the update date above, Google ads are not being served on this site. An AdSense site-verification meta tag, if configured, identifies the publisher account for ownership checks; it does not itself request an advertisement or activate advertising cookies.','If Google advertising is introduced, Google and other participating vendors may use cookies to show ads based on previous visits to this and other websites. Google’s advertising cookies can enable it and its partners to personalise ads using those visits. The applicable advertising and consent settings must be configured before that service is activated.','You can manage Google’s personalised-ad settings through My Ad Center. Choices for some other advertising vendors are also available through the Digital Advertising Alliance. These choices may be specific to a browser or device; this notice is not itself a consent mechanism.')+`<p><a href="https://myadcenter.google.com/">Google My Ad Center</a> · <a href="https://optout.aboutads.info/">Other participating vendors’ advertising choices</a> · <a href="https://policies.google.com/technologies/partner-sites">How Google uses data on partner sites</a></p>`+para('Before personalised Google ads are served to visitors in the EEA, UK or Switzerland, the advertising setup must use a Google-certified consent management platform integrated with the required framework. A general-purpose “accept cookies” button is not a substitute for that configuration. The current site does not load an ad script or present a button that claims to supply this advertising consent.'))+
    section('Payments, email and contact',para(copy['site.privacy.purchase.text'],'The free reading form does not ask for an email address. Private test checkout sends the selected birth details to our server to prepare and encrypt the order and report. Stripe receives the payment information needed for its checkout; card numbers are not sent to our report server. A saved recovery file contains a private access key, not birth details. If you select Remember this purchase, that key is also stored in your browser until you clear it. When purchase email delivery is enabled, Resend receives the checkout email address, report PDF and private recovery code to deliver your purchase. Keep that email private. Purchase delivery does not require marketing consent. Optional product updates require separate consent and email confirmation; you can unsubscribe without losing purchased reports. Contact emails and consent records are encrypted and kept separately from birth-chart inputs. Private Sandbox email delivery uses the provider’s test inbox, not the checkout address. If you contact the operator by email, your message and reply address are handled by the email providers involved. Share only the information needed for the question; do not send card details, identity documents or a complete birth-data backup.')+(identity.contactEmail ? `<p>Privacy questions: <a href="${mail(identity.contactEmail)}">${escape(identity.contactEmail)}</a>.</p>` : ''))+
    section('Removing or correcting information',para('You can edit birth details before calculating another reading. Use Your Data & Privacy in the interactive app to remove the last submitted form, named saved profiles and the current tab’s preview. Other open tabs may still hold a preview in memory, so close or reset those too.','Clearing site data does not delete a downloaded backup. To remove preferences, connection caches or all site storage, use your browser’s site-data controls. The site cannot retrieve a backup or recover browser information after you delete it.')+`<p><a class="public-button" href="/#your-data">Open browser-data controls →</a></p>`)+
    section('Updates',para('This notice must be reviewed when the site’s actual data practices change, including before paid accounts, email delivery, analytics or advertising are introduced. The latest version and update date will be published on this page.'))
}

function guide() {
  return update+para(copy['site.guide.intro'])+'<p>New to the symbols? Start with the <a href="/learn/">plain-English Saju guides</a>.</p>'+section('Begin with the right details',['date','time','place','check'].map(key => `<h3>${escape(copy[`site.guide.${key}.title`])}</h3>${para(copy[`site.guide.${key}.text`])}`).join('')+para('For example, someone born in London should enter the clock time recorded in London and select that birthplace. They should not convert the time to New York or Seoul first. If the time is unknown, the report leaves the hour out instead of treating midnight as a known birth hour.','A daylight-saving clock change can create a missing or repeated local time. If the form flags a time that did not exist, check the original record. A repeated clock time or an uncertain historical record may require additional care; a neat chart is not proof that the input was unambiguous.'))+
    section('Choose the question you want to explore',`<ul>${PUBLIC_SAMPLES.map(item => `<li><a href="/samples/${item.slug}/"><strong>${escape(item.title)}</strong></a>: ${escape(item.description)}</li>`).join('')}</ul>`+para('The focused reports explore different subjects. Are We Meant to Be? compares your chart with your partner’s; it does not award a scientific match percentage or decide whether a relationship should continue. Your Destiny Collection is one integrated ten-question reading across life, relationships, work, money and timing.'))+
    section('Read a theme, then test it against a real choice',para(copy['site.guide.bold.text'],copy['site.guide.habits.text'],copy['site.guide.chart.text'],'The situation guides add two possible approaches and the trade-off behind each one. Choose one that fits facts you can observe. A job offer needs its actual duties and expectations; a chart alone cannot tell you whether to accept it. A shared routine needs both people’s agreement; another person’s birthday cannot establish their motives.','Use the “three facts to write down” questions to record what was said or done. The keep-going and adjustment checks help you judge the trial. If an example is unhelpful or unsuitable, leave it. You do not need to make your life fit a reading.'))+
    section('Know which kind of page you are reading',para('A free snapshot is a short introduction calculated from the birth details entered in the form. A personal preview uses those details to show the product, question list and a short generic wording example. Public design samples show the report format and question titles without calculated personal answers.','The public previews can be read without entering any details. They do not include complete answers or personal chart results.'))+
    section('Year and monthly references',para('The default public annual example is for 2027. It compares the birth chart with the stated annual reference and twelve separately calculated monthly reference points. The report discloses the dates used.','A reference point on the 15th is not the beginning or full span of a Gregorian calendar month. Traditional solar-term boundaries can change the chart within that month. The monthly headlines are planning prompts; they do not promise that an event will occur in that calendar period.'))+
    section('Save details or keep a reading',para(copy['site.guide.save.text'],copy['site.guide.print.text'],'Static public examples can also be printed using your browser’s menu. A PDF is a copy of the example you are viewing, not a paid entitlement. Keep backups private and remove them separately if you no longer need them.'))+
    section('When you need help',`<p>The <a href="/help/">Help Centre</a> explains the reading flow and common questions. For browser storage and external connections, read the <a href="/privacy/">Privacy Notice</a>. For the scope of a traditional reflection report, see <a href="/use-and-limitations/">Use &amp; Limitations</a>.</p><a class="public-button" href="/samples/">View the report previews →</a>`)
}

function limitations() {
  return update+para('This page explains the scope and current use of The Fate Key’s free website. It is an informational reading notice, not a paid-service contract.')+
    section('A traditional reflection tool',para('Saju is a traditional symbolic framework. The readings offer questions about personality themes, work, relationships and everyday choices. They are not scientifically validated personality assessments, verified knowledge of your circumstances or guaranteed forecasts.','Your actual situation, preferences and the information available to you should guide your choices. A symbol cannot establish a person’s intentions, financial suitability, health condition or future outcome. Do not use a reading to replace qualified advice when a decision requires it.'))+
    section('Your inputs and someone else’s details',para('Check the birth date, local time and birthplace shown above a reading. If something is wrong, edit it before exploring the interpretation. Leave “I know my birth time” off if the time is unknown.','Only enter another person’s details when you are entitled to use them. Avoid putting sensitive personal information into a shared profile name or sending a complete backup when asking about a technical problem.'))+
    section('Public samples and service status',para('Public samples use example birth details and are clearly labelled. The illustrated covers are decorative. A saved or printed example does not confirm a purchase, professional consultation or certified assessment.','The free snapshot and personal preview are available to explore. Paid purchasing is not open, and the site does not currently issue reports after a payment. Planned prices are not a live offer to collect money. Before any paid service opens, its operator, delivery terms, support and applicable customer policies must be stated and reviewed.'))+
    section('Reading and using the content',para('You can read the public pages, use the available free tools and save a copy for your own reference. Do not present an example as a report prepared for a real customer or remove a sample label to imply that a purchase or endorsement occurred.','Source code and third-party components have their own licences. Source links are provided on the About page. The explanation here does not replace those licences or limit any rights that cannot lawfully be excluded.'))+
    section('Questions and changes',`<p>Read the <a href="/reading-guide/">Reading Guide</a> and <a href="/help/">Help Centre</a> for using the site, and the <a href="/privacy/">Privacy Notice</a> for information handling. The scope described here will be reviewed if the actual service changes.</p>`)
}

function editorial(identity: Identity) {
  return update+para('The Fate Key publishes English guides and traditional Saju readings for personal reflection. This page explains the difference between our sources, calculations and editorial examples, and how to raise a correction. The publisher name identifies this project; it does not imply a panel of independent experts.')+
    section('What is original to this site',para('Our guides explain how the current tool behaves and how to read its output. The worked chart tables are generated from the same calculation model as the public samples. The practical situations, conversation starters and review exercises are our editorial examples. They are not customer stories or events discovered from a birthday.','We link to cultural and technical references for the specific points they support. We do not reproduce another service’s paid reports or present a collection of copied descriptions as a personalised consultation.'))+
    section('How the writing is produced',para('The English reports are assembled from coded interpretation templates selected by calculated chart relationships. AI assistance is used for drafting, editing and checks. No independent human practitioner or scientific reviewer is represented as having certified these readings.','A personal preview responds to the birth inputs supplied to the tool. The public learning guides are separate educational articles. A common practical theme can appear in more than one reading; a shared theme does not establish that two people have the same personality or circumstances.'))+
    section('How to read our sources',`<ul><li><strong>Cultural references</strong> explain terminology and traditional conventions. They do not prove that a prediction is true.</li><li><strong>Calendar and time-zone references</strong> explain time records and boundaries. They do not endorse the interpretation.</li><li><strong>Source code</strong> documents the method this site implements, including its limits and the version checked.</li><li><strong>Worked examples</strong> show the method in use. Their inputs are fictional and disclosed.</li></ul>`+para('A software check can detect a regression or a mismatch with a reference case. It cannot establish that a person’s future follows a chart. When a convention differs between calculators, we explain the choice instead of describing one output as certain without evidence.'))+
    section('Standards for a useful passage',para('We aim to answer a clear question, explain unfamiliar language and connect each theme to its stated source. Everyday advice should include a specific situation, a small action and something the reader can observe afterward. A reader must be able to disagree with an interpretation.','We avoid invented reviews, audience counts, success rates, expert credentials and endorsements. Decorative images are illustrations. Chart labels are not medical diagnoses, investment recommendations, character judgements or a reason to pressure another person.'))+
    section('Corrections and updates',para('For an unclear explanation, identify the page and short passage. For a calculation concern, describe the convention or reference that appears different. Share only the details necessary to investigate; do not send someone else’s personal information or a full saved-profile backup.','When correcting a substantive explanation, we update the page and its review date. Public examples remain labelled as examples. If an error changes a calculation assumption, the associated explanation should change too. A date is a record of an update, not a guarantee that every possible case has been independently verified.')+(identity.contactEmail?'<p><a href="/contact/">Send a correction or question →</a></p>':'<p>Current guidance is available in the <a href="/help/">Help Centre</a>. A direct support address has not yet been published; please do not assume an unlisted address is monitored.</p>'))+
    section('Commercial transparency',para('Paid purchasing is not open at the date above. Planned prices describe a possible future service. Google ads are not currently served. Neither a sample report nor a printable copy is a payment confirmation.','If advertising or paid delivery is introduced, the relevant privacy, consent, pricing, delivery and customer information must match the service that actually operates. We do not describe a website update as Google approval.')+`<p><a href="/about/">About The Fate Key</a> · <a href="/privacy/">Privacy Notice</a> · <a href="/learn/">Read the guides</a></p>`)
}

function help(identity: Identity) {
  return update+para('Find answers before entering your details or choosing a reading. The free tool, educational guides and short public previews are available without an online account. Saved Details belongs to your browser; it is not a sign-in or a paid account.')+
    `<nav class="public-case-links" aria-label="Help topics"><a href="/reading-guide/">Enter and check birth details →</a><a href="/learn/unknown-birth-time/">Read without a birth time →</a><a href="/learn/birthplace-and-time-zones/">Check places and time conventions →</a><a href="/samples/">View the design and question previews →</a></nav>`+
    section('Frequently asked questions',['saju','time','location','free','payment','delivery','privacy'].map(key=>`<details><summary>${escape(copy[`home.faq.${key}.question`])}</summary>${para(copy[`home.faq.${key}.answer`])}</details>`).join(''))+
    section('If something does not work',para('For a birthplace search, check the selected country and choose a result rather than leaving only typed text. If the search is unavailable, the form offers coordinate entry. Make sure the location and inferred time zone match the birth record.','If the interactive reader cannot load, public guides and sample pages can still be read without JavaScript. To use the personal calculator, JavaScript must be available. Save or export any details you want to keep before clearing browser storage; the site cannot recover a deleted backup.','For an unexpected result, begin with the input summary and calculation notes. Check the recorded clock time, the selected hour, birthplace and birth-time option. Another calculator can use a different time convention, so compare those choices before treating different prose as an error.'))+
    section('Saved information and privacy',`<p>The <a href="/privacy/">Privacy Notice</a> explains local storage, place-search requests and external connections. <a href="/#your-data">Your Data &amp; Privacy</a> opens the interactive controls for clearing personal reading data on this browser. A downloaded backup is a separate file and must be deleted separately if you no longer want it.</p>`)+
    section('Questions and corrections',para('For a technical problem, the useful details are the page address, what you tried, the browser and any visible error message. For a wording problem, note the short passage and what was confusing. Please avoid sending identity documents, card information or a full birth-data backup.')+(identity.contactEmail?'<p><a href="/contact/">Contact The Fate Key →</a></p>':'<p>A direct support address is not yet published. These self-service pages are available now; there is no live support chat or email form on this page.</p>')+`<p><a href="/editorial-policy/">How we write, source and correct our content</a></p>`)
}

function contact(identity: Identity) {
  if (!identity.contactEmail) throw new Error('A contact page requires an approved public address')
  return update+para('Use the address below for questions about The Fate Key, a correction to a public reading or a privacy question. The current service provides free browser-based readings and public examples; paid purchasing is not open.')+`<p><a class="public-button" href="${mail(identity.contactEmail)}">${escape(identity.contactEmail)}</a></p>`+section('Include the useful details',para('For a page problem, include the page address, what you tried, your browser and device, and any visible error message. For a wording correction, quote the short passage and explain what is unclear.','Please do not send card information, identity documents or a full backup of birth details. A technical report usually does not need a person’s date or time of birth. Do not send someone else’s information unless you are entitled to share it.'))+section('Start with the guide',`<p>Common questions are covered in the <a href="/reading-guide/">Reading Guide</a> and <a href="/help/">Help Centre</a>. Browser storage controls are explained in the <a href="/privacy/">Privacy Notice</a>.</p>`)
}

function purchases() {
  return update + para('Public paid purchases are not open yet. Private test checkout does not charge real money. The delivery and recovery flow below describes the implemented purchase format; it does not mean live sales have started.') +
    section('What you receive', para('A verified payment unlocks the selected online report and a downloadable PDF. The report is prepared from the birth details confirmed before checkout. Check those details and the question preview before paying. Compatibility and the bundle require two people’s details. Prices are in USD and purchases are one-off.', 'Report preparation begins after the payment provider confirms payment. If it is still processing, retry the report page. A return from checkout alone is not proof of payment.')) +
    section('Keep your recovery code', para('Before you leave for Stripe, download the private purchase recovery code. After payment you can also download it from your report. Open the purchased-report page and enter that code to restore access on another device. When purchase email delivery is enabled, we also send your PDF, Report ID and private recovery code to your checkout email. Keep the saved code as a backup if the email is delayed or filtered. Sandbox sends only to the email provider’s test inbox.', 'You can choose to remember a purchase on a private device. This stores its access key in browser storage. Anyone with your recovery code or access to that browser may be able to open the purchased report. Keep the file private. Clearing browser storage removes a remembered key, but a separately saved recovery code can still be used.')) +
    `<p><a class="public-button" href="/#purchase">Open a purchased report →</a></p>` +
    section('Delivery problems, corrections and refunds', para('If you are charged twice for the same intended order, receive the wrong report, or cannot access a paid report, contact us with your order reference and a short description. Do not send card details or your private recovery code. We verify the payment and investigate the problem before arranging the appropriate correction or refund.', 'Refunds are reviewed by the operator; there is no automatic refund button. A completed full refund ends future online access to that order. It cannot delete a file you have already downloaded. A partial refund does not automatically end access.', 'Nothing in this notice excludes rights or remedies that cannot lawfully be excluded, including applicable Australian consumer guarantees. A personalised digital report is not automatically exempt from those rights.')) +
    `<p><a href="https://www.accc.gov.au/consumers/problem-with-a-product-or-service-you-bought/repair-replace-refund-cancel">Australian consumer rights information</a> · <a href="/contact/">Contact support</a> · <a href="/privacy/">Privacy Notice</a></p>`
}

export function renderDocument(page: Page, identity: Identity) {
  const title = `${page.title} | The Fate Key`
  const nav = `<a href="/learn/">Learn Saju</a><a href="/samples/">Sample Readings</a><a href="/reading-guide/">Reading Guide</a><a href="/about/">About</a>${identity.contactEmail ? '<a href="/contact/">Contact</a>' : ''}<a class="public-nav-free" href="/#birth-details">Free Reading →</a>`
  const footer = `<footer class="public-footer"><p>Traditional Saju interpretation for personal reflection. Your choices and circumstances matter; these are not guaranteed outcomes.</p><nav aria-label="Footer"><a href="/about/">About The Fate Key</a><a href="/learn/">Learn Saju</a><a href="/editorial-policy/">Writing &amp; Sources</a><a href="/privacy/">Privacy Notice</a><a href="/use-and-limitations/">Use &amp; Limitations</a><a href="/help/">Help Centre</a><a href="/purchases/">Purchases &amp; Recovery</a>${identity.contactEmail ? '<a href="/contact/">Contact</a>' : ''}</nav><p>${identity.operatorName ? `Seller: ${escape(identity.operatorName)} · ` : ''}© 2026 The Fate Key · <a href="https://github.com/rath/orrery">Orrery calculation engine</a></p></footer>`
  const content = `<div class="fate-public"><a class="public-skip" href="#public-content">Skip to content</a><header class="public-header"><a class="public-brand" href="/">${key}<span>The Fate Key<small>THE KEY TO A BRIGHTER TOMORROW</small></span></a><nav aria-label="Main navigation">${nav}</nav></header><main id="public-content">${page.path==='/' ? '' : `<header class="public-page-heading">${page.image ? `<img src="${escape(page.image)}" alt="" width="1200" height="800"/>` : ''}<p class="public-eyebrow">The Fate Key</p><h1>${escape(page.title)}</h1><p>${escape(page.description)}</p></header>`}${page.body}</main>${footer}</div>`
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width, initial-scale=1"/><title>${escape(title)}</title><meta name="description" content="${escape(page.description)}"/><link rel="canonical" href="${SITE_ORIGIN+page.path}"/><meta name="robots" content="${page.noindex ? 'noindex,follow' : 'index,follow'}"/><meta name="theme-color" content="#0b2435"/><meta property="og:type" content="${page.article ? 'article' : 'website'}"/><meta property="og:site_name" content="The Fate Key"/><meta property="og:title" content="${escape(title)}"/><meta property="og:description" content="${escape(page.description)}"/><meta property="og:url" content="${SITE_ORIGIN+page.path}"/><meta property="og:image" content="${SITE_ORIGIN+(page.image??'/images/fate-key-approved-hero.webp')}"/><meta name="twitter:card" content="summary_large_image"/><link rel="icon" href="/destiny-code-emblem.svg"/><link rel="stylesheet" href="/public-pages.css"/>${identity.accountId ? `<meta name="google-adsense-account" content="${identity.accountId}"/>` : ''}</head><body style="margin:0">${content}</body></html>`
}

export function publicContent(identity: Identity) {
  const pages: Page[] = [
    { path:'/', title:'Your Story Holds the Key',description:'Explore traditional Korean Saju through clear English readings, real-life questions and short public previews.',body:home()+section('New to Saju? Start here',para('Simple explanations, worked examples and answers to the questions behind your chart.')+learningCards(3)+'<p><a href="/learn/">Explore all five guides →</a></p>') },
    { path:'/about/',title:'About The Fate Key',description:'Our purpose, how the readings are made, the calculation engine and the limits of a symbolic interpretation.',body:about(identity) },
    { path:'/purchases/',title:'Purchases, Delivery & Recovery',description:'How private report delivery, purchase recovery and refund enquiries work.',body:purchases() },
    { path:'/privacy/',title:'Privacy Notice',description:'How birth details, saved browser profiles, place searches and external connections are handled by the current site.',body:privacy(identity) },
    { path:'/use-and-limitations/',title:'Use & Limitations',description:'The scope of the free website, public examples and traditional reflection readings.',body:limitations() },
    { path:'/reading-guide/',title:'Your Reading Guide',description:'Start with the right birth details, choose a subject and turn a reflection theme into something you can try.',body:guide() },
    { path:'/editorial-policy/',title:'Writing, Sources & Corrections',description:'How The Fate Key creates its guides and readings, uses AI assistance, labels examples and handles corrections.',body:editorial(identity) },
    { path:'/help/',title:'Help Centre',description:'Answers about birth details, free readings, saved information and the current service.',body:help(identity) },
    ...learningPages(),
    { path:'/samples/',title:'Explore the Sample Readings',description:'Read all seven complete fictional example reports, with every question answered in sample wording. Full personalised paid answers remain private.',body:update+para('Choose a subject and read its complete fictional example report. Each page shows the product design, every paid-report question and a clearly labelled illustrative answer for each one.','All examples use fictional wording. They are not calculated from Saju and do not contain customer birth details, personal chart conclusions or full paid customer reports.')+cards()+section('What is inside a sample',para('Each sample introduces the product, lists every question and shows a fictional example answer for each one. Your paid report adds interpretations based on your own chart, relevant timing where supported and the complete premium PDF.'))+section('Your Complete Destiny',`<p>Your Complete Destiny is one integrated ten-question reading across life, relationships, work, money and timing.</p><p><a href="/#my-report-bundle">Open the personal preview →</a></p>`)+`<p><a href="/about/">How these readings are made</a> · <a href="/reading-guide/">How to use a reading</a></p>` },
  ]
  for (const sample of PUBLIC_SAMPLES) {
    const title = sample.title
    const imageKind = 'imageKind' in sample ? sample.imageKind : sample.kind
    pages.push({path:`/samples/${sample.slug}/`,title:`${title} — Preview`,description:sample.description,image:`/images/reports/${imageKind}-v1-1200.webp`,body:safeSampleBody(sample.kind, title)})
  }
  if(identity.contactEmail)pages.push({path:'/contact/',title:'Contact The Fate Key',description:'Questions, corrections and privacy enquiries about this website.',body:contact(identity)})
  if (identity.liveSales) {
    for (const page of pages) {
      page.body = page.body
        .replace(/<p>[^<]*Paid purchasing is not open[^<]*<\/p>/g, para('Personalised English PDF reports are sold as one-off purchases in USD. Confirm your birth details and selected report before continuing to Stripe. Your bank may apply currency conversion or other fees.'))
        .replace(/<p>Public paid purchases are not open yet[^<]*<\/p>/g, para('Purchase your selected personalised English report through Stripe. Payment confirmation unlocks online access, PDF download and delivery to your checkout email. Keep your private recovery code.'))
        .replace('It does not currently operate paid checkout or customer accounts.', 'Paid reports use Stripe Checkout; there is no customer sign-in account.')
        .replace('The current service provides free browser-based readings and public examples; paid purchasing is not open.', 'The service provides free examples and personalised paid English PDF reports. Include your order reference for purchase support.')
        .replace('Private test checkout sends the selected birth details', 'Checkout sends the selected birth details')
        .replace('When purchase email delivery is enabled,', 'For paid purchases,')
        .replace('Private Sandbox email delivery uses the provider’s test inbox, not the checkout address.', 'Test environments use a separate test inbox. Live purchase delivery uses the email entered at checkout.')
        .replace('Sandbox sends only to the email provider’s test inbox.', 'If delivery is delayed, use your recovery code to download the report and contact support with the order reference.')
        .replace('Free access and planned reports', 'Free previews and paid reports')
        .replace(/<p>[^<]*planned prices[^<]*<\/p>/gi, para('Report prices are shown in USD before checkout. Payment is collected by Stripe. Free previews and public samples remain available without payment.'))
      if (page.path === '/privacy/') page.body += section('Paid order records', para('The server stores encrypted birth inputs, the purchased report and purchase contact details to deliver and recover your report. Stripe stores payment records under its own policies; Resend processes purchase email and attachments. Contact support to request access, correction or deletion. Records needed for payment, tax, fraud prevention or a dispute may need to be retained. Marketing is not required to buy; promotional email collection is not enabled in this release.'))
      if (identity.operatorName && ['/about/','/purchases/','/contact/'].includes(page.path)) page.body = para(`Seller: ${identity.operatorName}. Brand: THE FATE KEY. Support: ${identity.contactEmail}.`) + page.body
    }
  }
  return pages
}

export function sitemap(identity: Identity) {
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${publicPaths(identity.contactEmail).map(path=>`  <url><loc>${SITE_ORIGIN+path}</loc><lastmod>${PUBLISHING_UPDATED}</lastmod></url>`).join('\n')}\n</urlset>\n`
}
